from _lib import File
F=File('pre2020_ktm450','o-k45','KTM 450 SX-F 2011-2019 by generation (2011-2012 carburetted linkage bike, 2013-2015, 2016-2018, 2019): what changed, dyno and weight, tester settings, electronics, known problems and fixes; shared items carried to the Husqvarna FC 450 (knowledge push 2026-11)','KTM',['450 SX-F','FC 450'],list(range(2011,2020)))
R=F.R; M='magazine'; C=['450 SX-F']
bg=F.src(M,"Motocross Action - KTM 450SXF buyer's guide 2007 to 2020","https://motocrossactionmag.com/ktm-450sxf-buyers-guide-everything-you-need-to-know-from-2007-to-2020","2020")

R('identity','450 SX-F generations 2011-2019',C,list(range(2011,2020)),"KTM 450 SX-F milestones: 2011 rising-rate linkage replaces the linkless PDS shock on a new steel frame (still carburetted); 2013 new single-cam fuel-injected engine with plain bearings and a new chassis; 2015 WP 4CS fork on US bikes, 20 mm front axle and Excel rims; 2016 all-new lighter platform (227 lb); 2017 WP AER 48 air fork, traction control and a two-map switch (222 lb); 2019 new frame 10% stiffer in torsion with a cylinder head 15 mm lower.",{'2011':'linkage rear suspension','2013':'fuel injection, new engine and chassis','2015':'WP 4CS fork','2016':'new platform','2017':'WP AER 48 air fork, traction control','2019':'new frame and head'},'OEM',bg)

# ---------------- 2011-2012
s=F.src(M,"Motocross Action - 2011 KTM 450SXF test","https://motocrossactionmag.com/2011-ktm-450sxf-motocross-test-everything-you-need-to-know-about-the-big-bore-ktm-motocross-bike","2010")
G=[2011,2012]
R('identity','2011 changes',C,[2011],"2011 450 SX-F changes: a new chromoly frame with a rising-rate linkage in place of PDS, slimmer and lower bodywork, a tool-free airbox with a new filter and boot, a muffler outlet enlarged from 33 to 36 mm, a shock 4 mm shorter (rear 13 mm lower at the axle) and a nylon preload ring. The carburetted engine and its jetting are unchanged. List price $8,799.",{'msrp_usd':8799,'rear':'linkage'},'OEM',s)
R('power_feel','2011-2012 dyno and weight',C,G,"On a magazine dyno the carburetted 450 SX-F made 53.92 hp at 8,200 rpm in 2011 and 53.24 hp at 8,800 rpm in 2012, still holding 49 hp at 11,000 rpm. It weighed 242-243 lb without fuel. Gentle at low rpm and building steadily to a strong top end, with no abrupt throttle response.",{'peak_hp_2011':53.92,'peak_hp_2012':53.24,'weight_lb':'242-243'},'MEASURED',s,'high')
R('setups','2011-2012 tester settings',C,G,"A magazine test crew's 2011-2012 450 SX-F setup: fork 0.50 kg/mm springs, compression 12 clicks out, rebound 12 out, legs 5 mm up; add 10 cc of oil for fast riders or if it dives, take 10 cc out for small riders. Shock stock 5.7 kg/mm spring (6.0 for riders around 200 lb), 100 mm sag, high-speed compression 1-1/4 turns out, low-speed 12 clicks out, rebound 12 out.",{'fork':'0.50 kg/mm, comp 12 out, reb 12 out, 5 mm up','shock':'5.7 kg/mm (6.0 near 200 lb), sag 100 mm, HSC 1-1/4 turns, LSC 12 out, reb 12 out'},'TUNER',s)
R('setups','2011-2012 jetting',C,G,"Jetting for the 2011-2012 450 SX-F (41 mm Keihin FCR): 185 main, 42 pilot, OBDTQ needle on the 6th clip from the top, 50 leak jet, fuel screw 1-3/4 turns out. If it will not fire on the starter, richen the fuel screw.",{'main':185,'pilot':42,'needle':'OBDTQ, 6th clip','leak_jet':50,'fuel_screw':'1-3/4 turns'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2012 KTM 450SXF test","https://motocrossactionmag.com/mxas-2012-ktm-450sxf-motocross-test-the-bike-that-blows-holes-in-the-fuel-injected-theory","2011")
R('identity','2012 changes',C,[2012],"2012 450 SX-F changes: a new clutch with a single Belleville (diaphragm) spring, a smaller steel basket and rubber-damped hub in place of six coil springs, the rear brake bleed hole repositioned so it no longer touches the master-cylinder seals, slightly more fork compression damping, white airbox and side panels and a holeshot device. The engine is otherwise unchanged and still carburetted.",{'clutch':'Belleville spring, steel basket'},'OEM',s2)
R('setups','2011-2015 gearing',C,[2011,2012,2013,2014,2015],"Stock gearing on the 2011-2015 450 SX-F is 14/52 (3.71). Testers found it tall and ran 14/53; faster riders went to 13/50 (3.85) and one factory rider used 13/51.",{'stock':'14/52','options':'14/53; 13/50 for fast riders'},'TUNER',s2)
R('known_issues','2011-2012 weak points and fixes',C,G,"Tester findings on the 2011-2012 450 SX-F: the nylon shock preload ring is hard to turn and deforms (the 2010 aluminium ring does not fit; a worm-drive aftermarket adjuster does), the radiator overflow can vent onto the hot pipe (run a longer hose under the cases), the airbox backfire screen can fray and be drawn into the intake (use the two-stroke filter cage without a screen), the rims flat-spot at the rim lock and the spokes need watching when new, the stock bars are low (12 mm or 19 mm taller bends), and the heavy stock battery can be replaced with a lithium one to save 2.5-3 lb.",{},'TUNER',s2)
R('chassis','2011-2012 handling',C,G,"The 2011-2012 450 SX-F has a 63.5 degree steering head angle. It tracks accurately, is stable at speed and less twitchy than the PDS bikes, but will not turn as tightly as the sharpest-steering Japanese 450 of the time.",{'head_angle_deg':63.5},'TUNER',s2)

# ---------------- 2013-2015
s=F.src(M,"Motocross Action - 2013 KTM 450SXF test","https://motocrossactionmag.com/mxas-2013-ktm-450sxf-motocross-test-if-you-are-loyal-to-your-brand-it-is-time-to-start-thinking-about-a-shift-in-allegiances","2012")
G=[2013,2014,2015]
R('identity','2013 redesign',C,G,"The 2013 450 SX-F was new: a single-overhead-cam, fuel-injected engine with die-cast cases and plain bearings at both ends of the rod, a five-speed gearbox, a hydraulic diaphragm-spring clutch, a redesigned frame and airbox, a rear axle 5 mm larger and a stronger one-piece swingarm. It lost about 3 lb. This platform ran 2013-2015.",{'fuel_system':'fuel injection','gearbox':'5-speed'},'OEM',s)
R('power_feel','2013 dyno and weight',C,[2013],"On a magazine dyno the 2013 450 SX-F peaked at 56.95 hp at 9,400 rpm and was 6 hp ahead of the 2013 KX450F at 11,000 rpm. It weighed 240 lb. Mild right off idle, then it builds all the way up; it is faster than it feels.",{'peak_hp':56.95,'peak_rpm':9400,'weight_lb':240},'MEASURED',s,'high')
R('setups','2013 tester settings',C,[2013,2014],"A magazine test crew's 2013 450 SX-F setup: fork 0.50 kg/mm springs, 390 cc oil, compression 12 clicks out, rebound 12 out, legs 5 mm up. Shock 5.7 kg/mm spring, 100 mm sag, high-speed compression 1-1/4 turns out, low-speed 12 clicks out, rebound 12 out.",{'fork':'0.50 kg/mm, 390 cc, comp 12 out, reb 12 out, 5 mm up','shock':'5.7 kg/mm, sag 100 mm, HSC 1-1/4 turns, LSC 12 out, reb 12 out'},'TUNER',s,'medium','Tested on the 2013. The 2014 kept the same fork and shock hardware with a little more fork compression damping.')
R('known_issues','2013-2015 weak points and fixes',C,G,"Tester findings on the 2013-2015 450 SX-F: the exhaust cannot come off without removing the shock, the stock clutch spring is soft (the 280-rated Belleville spring in place of the 250; KTM fitted a stiffer spring from 2014), the seat foam goes soft once broken in, the shift lever tip sits too low and one spline up is too high, and on 2013-2014 bikes the rims are weak and the spokes next to the rear rim lock work loose (KTM changed to Excel rims for 2015).",{'clutch_spring':'280 in place of 250'},'TUNER',s)
R('identity','2014 changes',C,[2014],"2014 450 SX-F changes: a stiffer clutch spring, the shorter 250 SX-F-style muffler, and more compression damping in the WP fork.",{},'OEM',bg)
s=F.src(M,"Motocross Action - 2015 KTM 450SXF test","https://motocrossactionmag.com/2015-ktm450sxf-review","2014")
R('identity','2015 changes',C,[2015],"2015 450 SX-F changes: WP 4CS (four-chamber) fork on US bikes, 4.8 N/mm fork springs (was 5.0), a 20 mm front axle (was 25) with its offset moved 2 mm rearward (35 to 33 mm), a new linkage bell crank with a pull rod 2.5 mm longer, a shock 4 mm longer (rear seat height 5 mm lower), a forged one-piece frame cross tube, an orange frame, black Excel rims and Dunlop MX52 tyres. The engine is unchanged; the bike is 466 g lighter.",{'fork':'WP 4CS','front_axle_mm':20,'pull_rod':'+2.5 mm','clamp_offset_mm':22},'OEM',s)
R('setups','2015 tester settings (4CS)',C,[2015],"A magazine test crew's 2015 450 SX-F setup: fork stock 4.8 N/mm springs, compression 17 clicks out (stock 15), rebound 9 out (stock 15), legs 5 mm up, oil lowered 10 cc if it is not bottoming. Shock 5.7 kg/mm spring, 103 mm sag, high-speed compression 1-3/4 turns out (stock 2), low-speed 15 clicks out, rebound 10 out (stock 15). The stock 2015 shock spring measured softer than its label (5.62); heavier or faster riders used the stiffer 2014 spring.",{'fork':'4.8 N/mm, comp 17 out (stock 15), reb 9 out (stock 15), 5 mm up','shock':'5.7 kg/mm, sag 103 mm, HSC 1-3/4 turns (stock 2), LSC 15 out, reb 10 out (stock 15)'},'TUNER',s)
R('chassis','2015 handling',C,[2015],"The 2015 450 SX-F was rated the best all-round handling 450 of its year: neutral, with little oversteer or understeer. Clamp offset is 22 mm; moving the axle back 2 mm acts like a 20 mm clamp, adding trail and shortening the wheelbase. The open-style fork guards let rocks ding the tubes.",{'offset_mm':22},'TUNER',s)

# ---------------- 2016-2018
s=F.src(M,"Motocross Action - 2016 KTM 450SXF race test","https://motocrossactionmag.com/mxa-race-test-2016-ktm-450sxf","2015")
G=[2016,2017,2018]
R('identity','2016 platform',C,G,"The 2016 450 SX-F (first sold as the 2015-1/2 Factory Edition) is an all-new, much lighter bike: 227 lb, 7.9 lb less than the 2015. For 2016 the 4CS fork was revalved softer, the shock's mid and high-speed damping reduced, the frame painted black and the tyres changed to Dunlop MX32. This platform ran 2016-2018.",{'weight_lb':227},'OEM',s)
R('power_feel','2016 dyno',C,[2016],"On a magazine dyno the 2016 450 SX-F made 57.98 hp and 36.5 lb-ft. Easy to ride, with a smooth pull from bottom to top rather than a hit.",{'peak_hp':57.98,'peak_torque_lbft':36.5,'weight_lb':227},'MEASURED',s,'high')
R('setups','2016 tester settings (4CS)',C,[2016],"A magazine test crew's 2016 450 SX-F setup: fork 4.8 N/mm springs, compression 10 clicks out for intermediates and up to 20 out for novices (stock 15), rebound 15 out, legs 5 mm up, 10 cc more oil per leg for fast riders. Shock 45 N/mm spring in place of the stock 48 for riders under about 190 lb, 105 mm sag (WP recommends 110), high-speed compression 1-3/4 turns out (stock 2), low-speed 15 clicks out, rebound 12 out (stock 15). Pros added one tooth at the rear.",{'fork':'comp 10 out (int) to 20 out (novice), reb 15 out, 5 mm up','shock':'45 N/mm (stock 48), sag 105 mm, HSC 1-3/4 turns, LSC 15 out, reb 12 out'},'TUNER',s)
R('known_issues','2016 rectifier',C,[2016],"The 2016 450 SX-F has a downsized regulator/rectifier that is prone to failing; the unit from the 2015 or 2017 bike is the replacement.",{},'TUNER',bg)
s=F.src(M,"Motocross Action - 2017 KTM 450SXF race test","https://motocrossactionmag.com/mxa-race-test-2017-ktm-450sxf","2016")
R('identity','2017 changes',C,[2017],"2017 450 SX-F changes: WP AER 48 air fork in place of the 4CS (3.6 lb lighter), a stiffer top clamp, a 45 N/mm shock spring (was 48), a handlebar multi-switch with two maps, launch control and traction control, a rear brake pedal 10 mm longer with milder pads, lighter cast head stays, an hour meter and a lighter clutch basket. Weight fell to 222 lb.",{'fork':'WP AER 48 (air)','shock_spring':'45 N/mm','weight_lb':222},'OEM',s)
R('setups','2017 tester settings (AER)',C,[2017],"A magazine test crew's 2017 450 SX-F setup: fork air 135 psi for novices, 145 for intermediates, 150 for experts, compression 15 clicks out, rebound 15 out, legs at the third line. Shock stock 45 N/mm spring (48 for riders around 200 lb), 105 mm sag (stock recommendation 110), high-speed compression 1-3/4 turns out (stock 2), low-speed 15 clicks out, rebound 10 out (stock 15).",{'fork_psi':'135 novice / 145 intermediate / 150 expert','fork':'comp 15 out, reb 15 out, third line','shock':'45 N/mm, sag 105 mm, HSC 1-3/4 turns, LSC 15 out, reb 10 out'},'TUNER',s)
R('ecu_electronics','2017-2018 map switch, traction and launch control',C,[2017,2018],"On the 2017-2018 450 SX-F map 1 is standard and map 2 is aggressive; there is no mellow map, and every magazine tester chose map 2. Traction control retards the ignition when it sees the revs run away, so it works like a third, calmer map for hardpack and mud. Launch control: press the map and TC buttons together until the light flashes; it cancels if the revs drop by more than 30%. On a cold morning, pulse the starter briefly three or four times about 30 seconds apart to run the fuel pump before cranking.",{'map_1':'standard','map_2':'aggressive','tc':'retards ignition on rev spikes'},'TUNER',s)
s=F.src(M,"Motocross Action - 2018 KTM 450SXF race test","https://motocrossactionmag.com/mxa-race-test-2018-ktm-450sxf","2017")
R('identity','2018 changes',C,[2018],"2018 450 SX-F changes: AER fork with a new air seal, pistons and valving, a shock revalved to match, a battery with twice the cold-cranking current, nitrided clutch steels, an updated gearbox bearing and shift star, radiator guards with drain holes and an orange frame.",{},'OEM',s)
R('setups','2018 tester settings (AER)',C,[2018],"A magazine test crew's 2018 450 SX-F setup: fork air 145 psi (stock 156; most riders ended up between 130 and 150), compression 20 clicks out (stock 12), rebound 15 out (stock 12), legs at the third line. Shock 45 N/mm spring (48 over about 180 lb), 105 mm sag (stock 110), high-speed compression 1-3/4 turns out (stock 2), low-speed 15 clicks out, rebound 10 out (stock 15). Fork pressure rises by up to 4 psi over a long moto.",{'fork_psi':'145 (stock 156; range 130-150)','fork':'comp 20 out (stock 12), reb 15 out (stock 12), third line','shock':'45 N/mm, sag 105 mm, HSC 1-3/4 turns, LSC 15 out, reb 10 out (stock 15)'},'TUNER',s)
R('known_issues','2016-2018 weak points and fixes',C+['FC 450'],G,"Repeated tester findings on the 2016-2018 KTM-built 450s: rear sprocket bolts and the spokes beside the rim lock loosen and need checking every ride (one test bike broke five front spokes), neutral is hard to find at a standstill, the exhaust cannot come off without removing the shock, the fork air bleed screw strips (use a T-handle, not the Torx bit), the nylon shock preload ring is best levered round with a long screwdriver rather than punched, the fuel-pump relay with the blue cap can fall off its rubber strap, metal tie-down hooks can kink the front brake hose, and on 2017-2018 bikes the one-piece top bar clamp twists its rubber mounts.",{},'TUNER',s)

# ---------------- 2019
s=F.src(M,"Motocross Action - 2019 KTM 450SXF race test","https://motocrossactionmag.com/mxa-race-test-the-real-test-of-the-2019-ktm-450sxf","2018")
R('identity','2019 changes',C,[2019],"2019 450 SX-F changes: a frame 10% stiffer in torsion with new head-tube gussets, a cylinder head 15 mm lower and over 1 lb lighter, Pankl gear sets on the same ratios, a three-piece exhaust that comes off without removing the shock, radiators 12 mm lower with 20% more coolant, a flatter seat, a swingarm 5 mm longer, clamps 5 mm wider, an AER fork with a new base valve and half the rebound-side air volume, and the fuel pump moved to the other side of the tank.",{'frame':'10% stiffer in torsion','swingarm':'+5 mm'},'OEM',s)
R('power_feel','2019 dyno and weight',C,[2019],"On a magazine dyno the 2019 450 SX-F peaked at 57.13 hp stock and 58.12 hp with the airbox cover opened up, which also averaged 1.5 hp more from 7,500 to 10,500 rpm. It weighed 223 lb, the lightest 450 of its year by up to 19 lb.",{'peak_hp':57.13,'peak_hp_open_airbox':58.12,'weight_lb':223},'MEASURED',s,'high')
R('setups','2019 tester settings (AER)',C,[2019],"A magazine test crew's 2019 450 SX-F setup: fork air 145 psi (stock 151; light or vet riders about 130, and it starts to hang down under braking near 128), compression 25 clicks out (stock 15), rebound 17 out (stock 15), legs at the third line, 10 cc of oil removed from the damping leg for slower riders. Shock stock 45 N/mm spring (48 over 200 lb, 42 under 150 lb), 105 mm sag (WP says 110), high-speed compression 1-3/4 turns out (stock 2), low-speed 15 clicks out, rebound 10 out (stock 15). Free sag should be 30-40 mm: more means the spring is too stiff, less means too soft.",{'fork_psi':'145 (stock 151)','fork':'comp 25 out (stock 15), reb 17 out (stock 15), third line','shock':'45 N/mm, sag 105 mm, HSC 1-3/4 turns, LSC 15 out, reb 10 out','free_sag_mm':'30-40'},'TUNER',s)
R('engine_mods','2019 airbox cover',C,[2019],"The 2019 450 SX-F airbox cover restricts the engine. Cutting the winglet off the inside of the cover, or drilling holes in it, sharpened throttle response and added about 1 hp at peak in dyno testing.",{'gain_hp':'about 1 at peak, 1.5 average 7,500-10,500 rpm'},'MEASURED',s)

if __name__=='__main__': F.write()
